const kb = [
  { gep: "Truxor T40", jelenseg: "füstöl motor fogy az olaj kék szürke füst", kategoria: "Motor/Olajrendszer", surgosseg: "Kritikus", lepes: "AZONNAL leállítani! Hengerfejtömítés és dugattyúgyűrű ellenőrzése.", alkatreszek: "Hengerfejtömítés (TRX-ENG-001), 5W-40 Motorolaj (O-5W40-10L)" },
  { gep: "Truxor T40", jelenseg: "vágófej nem mozog lassan reagál hidraulika", kategoria: "Hidraulika", surgosseg: "Magas", lepes: "Hidraulika folyadék szint és nyomócsövek ellenőrzése, szeleptömb tisztítás.", alkatreszek: "Hidraulika olaj HLP46 (O-HYD-46), Nagynyomású tömlő (TRX-HYD-044)" },
  { gep: "Truxor T40", jelenseg: "eltört elhajlott vágókés t-alakú", kategoria: "Vágószerkezet/Kopóalkatrész", surgosseg: "Normál", lepes: "Sérült kés leszerelése és cseréje.", alkatreszek: "T-vágókés (TRX-BLD-T01), M10 rögzítőcsavar szett (CSAV-M10-X)" },
  { gep: "Honda WB30XT", jelenseg: "zörög fémes hang súrlódás szivattyú", kategoria: "Csapágy/Mechanika", surgosseg: "Magas", lepes: "Leállítás! Főtengely csapágy vagy vízkerék csapágy kopott.", alkatreszek: "Csapágykészlet SKF-6204 (HND-BRG-6204), Vízpumpa szimering (HND-SEAL-01)" },
  { gep: "Honda WB30XT", jelenseg: "nehezen indul dadog ingadozik alapjárat", kategoria: "Üzemanyagrendszer", surgosseg: "Normál", lepes: "Karburátor tisztítás, gyújtógyertya ellenőrzés és csere.", alkatreszek: "NGK BPR6ES gyújtógyertya (NGK-BPR6ES), Karburátor tisztító spray (KEM-CARB-01)" },
  { gep: "Kotróhajó", jelenseg: "szívóteljesítmény csökken eldugult cső", kategoria: "Szívórendszer", surgosseg: "Normál", lepes: "Szivattyú leállítása, szívófej kiemelése és megtisztítása.", alkatreszek: "Nincs szükséges alkatrész" },
  { gep: "Kotróhajó", jelenseg: "úszótest ponton szelep ereszt süllyed hajó", kategoria: "Biztonság/Hajótest", surgosseg: "Kritikus", lepes: "AZONNAL partra vontatni! Szelep csere, rekesz szárazra szivattyúzása.", alkatreszek: "Biztonsági légtelenítő szelep (PONT-VALVE-002), Tömítőpaszta (KEM-SIL-05)" }
];

const q = query.toLowerCase();
const words = q.split(/\s+/).filter(w => w.length > 2);
const results = kb.filter(item => {
  const text = (item.gep + ' ' + item.jelenseg).toLowerCase();
  return words.some(w => text.includes(w));
});

if (results.length === 0) {
  return "Nincs találat. Ismert gépek: Truxor T40, Honda WB30XT (vízszivattyú), Kotróhajó.";
}

return results.map(r =>
  `GÉP: ${r.gep}\nKATEGÓRIA: ${r.kategoria}\nSÜRGŐSSÉG: ${r.surgosseg}\nJAVASLAT: ${r.lepes}\nALKATRÉSZEK: ${r.alkatreszek}`
).join('\n\n');

try {
  const parsedData = JSON.parse($input.first().json.output);
  return {
    json: {
      status: "success",
      adatok: parsedData
    }
  };
} catch (e) {
  return {
    json: {
      status: "error",
      hiba: "Nem érvényes JSON",
      nyers_szoveg: $input.first().json.output
    }
  };
}

